#!/usr/bin/env python3
"""SPROCKET W27 exact-source CPU experiment (verified gzip transport).
Use --print-source to inspect the original 14,658-byte readable source.
Only trains auxiliary rank-24 action arbitration; zero root/LoRA updates.
Requires worm_train_v25.py and local W24/W25 source-evidence ZIPs.
"""
import base64,gzip,hashlib,sys
_SOURCE=""
def _source():
    raw=gzip.decompress(base64.b64decode(_SOURCE))
    assert hashlib.sha256(raw).hexdigest()=="4e29e0f1b4126578011ce452783ee34403804001b47a3d57226f453564a5ca54"
    return raw
if __name__=="__main__" and sys.argv[1:]==["--print-source"]:
    sys.stdout.buffer.write(_source())
else:
    exec(compile(_source().decode("utf-8"),__file__,"exec"),globals())
